# Format: Feld-ID=Beschreibung

# Für HL7-Felder:
# PID_5=Patientenname
# PID_7=Geburtsdatum
# OBX_5=Laborwert Resultat

# Für Text-/CSV-Dateien:
# Feld 1=Auftragsnummer
# Feld 2=Kundenname
# Feld 3=Erstellungsdatum


PID_3 = SuvaPID~OpalePID
PV1_3 = Siehe PV1_3.1 bis PV1_3.7
PV1_3.1 = Fachabteilung
PV1_3.2 = Zimmernummer
PV1_3.3 = Bettplatz
PV1_3.4 = Standort
PV1_3.5 = Status des Orts
PV1_3.6 = Art des Aufenthalts
PV1_3.7 = Gebaeude
PV1_20 = Textformat erwartet (z.B. allgemein) 

